                  <img
                    className="kk-bonus-mark"
                    src="/kilo-night-v3/logo-kilo-king.png"
                    alt="Kilo King"
                  />
                  <div className="kk-bonus-spins">
                    <img
                      className="kk-plate"
                      src="/kilo-night-v3/ui-plate.svg"
                      alt=""
                    />
                    <div className="kk-plate-copy">
