                      })}
                    </div>
                  </div>
                  <div className="kk-bonus-pay">
                    <img
                      className="kk-plate"
                      src="/kilo-night-v3/ui-plate.svg"
                      alt=""
                    />
                    <div className="kk-plate-copy">
                      <span className="kk-eyebrow">Multiplier</span>
                      <b className="kk-mult">×{hud.mult}</b>
                    </div>
                  </div>
                  {capNotice ? (
                    <span className="kk-next kk-cap-note">Max win reached</span>
                  ) : hud.maxed || hud.nextMult == null ? (
                    <span className="kk-next">Max level</span>
                  ) : (
                    <span className="kk-next">
                      Next +{hud.nextSpins} spins · ×{hud.nextMult}
                    </span>
                  )}
                </div>
              ) : (
                <>
                  <div className="kk-crest-status">
                    <p className="kk-event">{caption}</p>
                  </div>
                </>
              )}
            </div>
            <div className="kk-canvas-wrap" data-testid="reel-host">
              <ReelStage onReady={onReady} />
              <StageSurround
                width={layout.reelWidth}
                height={layout.reelHeight}
                mode={layout.compact ? "mini" : layout.mode}
              />
            </div>
          </div>
          <div
            className="kk-modular-controls"
            data-control-system="v32"
            data-collection-phase={collection?.phase ?? "idle"}
            style={{ width: dock.width, height: dock.height }}
          >
            <SlotControls
              layout={dock}
              theme={KILO_CONTROL_THEME}
              icons={{ buy: <FeatureMark /> }}
              jurisdiction={jurisdiction}
              spinRef={spinButton}
              menuRef={menuButton}
              menuPopupId="kilo-quick-settings"
              bonusAnchorClassName="kk-bonus-win"
              state={{
                balance: money(bank),
                win: money(hud?.active ? shownBonus : shownWin),
                bet: money(stake),
                wager: money(mode === "ante" ? cost : stake),
                currency: "LGC",
                ante: mode === "ante",
                speed: effectiveSpeed,
                menuOpen: settingsOpen,
                feature: hud?.active
                  ? { remaining: hud.left ?? 0, multiplier: hud.mult }
                  : undefined,
                busy,
                autoRemaining: autoLeft,
                ready,
                locked: controlsLocked,
                spinDisabled:
                  summary != null ||
                  !ready ||
                  (!busy && (afford || !splashStakeOk(stake, mode))),
                spinDisabledReason: !ready
                  ? "Loading"
                  : afford
                    ? "Insufficient balance"
                    : !busy && !splashStakeOk(stake, mode)
                      ? "Bet unavailable"
                      : undefined,
                minimumBet: stake === STAKES[0],
                maximumBet: stake === STAKES.at(-1),
                charge: busy
                  ? {
                      label: reviewing
                        ? "Replay"
                        : hud?.active
                          ? "Free spins"
                          : "Spinning",
                    }
                  : { amount: money(cost) },
                awardLanded,
                reducedMotion,
              }}
              actions={{
                menu: () => {
                  uiTap();
                  autoRunner.current?.stop();
                  setPanel(false);
                  setSettingsOpen((open) => !open);
                },
                turbo: () => {
                  uiTap();
                  changePreferences({
                    ...preferences,
                    speed:
                      effectiveSpeed === "normal"
                        ? "turbo"
                        : effectiveSpeed === "turbo"
                          ? "super"
                          : "normal",
                  });
                },
                bet: () => {
                  uiTap();
                  setPanel(false);
                  setBetReturn("game");
                  setBetPanel(true);
                },
                minus: () => {
                  if (!busyRef.current)
                    setStake(
                      STAKES[
                        Math.max(0, STAKES.findIndex((n) => n === stake) - 1)
                      ]!,
                    );
                },
                plus: () => {
                  if (!busyRef.current)
                    setStake(
                      STAKES[
                        Math.min(
                          STAKES.length - 1,
                          STAKES.findIndex((n) => n === stake) + 1,
                        )
                      ]!,
                    );
                },
                auto: () => {
                  if (jurisdiction.disabledAutoplay) return;
                  uiTap();
                  if (autoLeft) autoRunner.current?.stop();
                  else setAutoPanel(true);
                },
                spin: () => {
                  if (autoLeft) autoRunner.current?.stop();
                  else if (busy) skip();
                  else {
                    primeAudio();
                    void play();
                  }
                },
                buy: () => {
                  if (jurisdiction.disabledBuyFeature) return;
                  uiTap();
                  setPanel(false);
                  setBuyPanel(true);
                },
              }}
            />
          </div>
        </div>
        {note && !reviewing ? (
          <p role="status" className="kk-notice">
            {note}
          </p>
        ) : null}
        {help ? (
          <Dialog
            label="Game rules"
            className="kk-dialog kk-rules"
            onClose={() => setHelp(false)}
          >
            <PanelHeader
              title="Rules & paytable"
              onClose={() => setHelp(false)}
              onBack={() => {
                setHelp(false);
                setSettingsOpen(true);
              }}
            />
            <div className="kk-dialog-body">
              <button
                type="button"
                className="kk-info-settings"
                onClick={() => {
                  setHelp(false);
                  setPreferencesOpen(true);
                }}
              >
                Game settings · Speed & motion
              </button>
              <details className="kk-control-guide">
                <summary>Controls</summary>
                <dl>
                  <div>
                    <dt>Spin / Spacebar</dt>
                    <dd>
                      Starts one round at the displayed cost. During a round,
                      Skip advances its presentation.
                    </dd>
                  </div>
                  <div>
                    <dt>Bet & chevrons</dt>
                    <dd>
                      Open the bet selector or move to the next available bet.
                      Ante is on the Features page and costs 1.5× the base bet.
                      The Bet readout shows the active wager.
                    </dd>
                  </div>
                  <div>
                    <dt>Lightning</dt>
                    <dd>
                      Cycles Normal, Turbo and Super turbo. On phones and small
                      popouts, use Menu → Info → Game settings. Speed changes
                      presentation only.
                    </dd>
                  </div>
                  <div>
                    <dt>Auto arrows</dt>
                    <dd>
                      Choose and confirm a finite number of spins. In small
                      popout views, use Menu → Info → Game settings → Auto
                      spins. Stop cancels the remaining queue; the current round
                      completes.
                    </dd>
                  </div>
                  <div>
                    <dt>Crown & hook</dt>
                    <dd>
                      Opens the feature catalogue. Selecting a feature opens its
                      cost confirmation before a purchase.
                    </dd>
                  </div>
                  <div>
                    <dt>Menu</dt>
                    <dd>
                      Opens Info, Music and Sound. Info includes rules, paytable
                      and Game settings for speed and motion.
                    </dd>
                  </div>
                </dl>
              </details>
              <Paytable stake={stake} />
              <h2>Symbol guide</h2>
              <p>
                {SCATTER_IS_KING
                  ? "KING emblem. The crown with no cash amount. It is the only scatter."
                  : "Scatter. The wrapped package marked KILO and SCATTER. It shows no cash amount. It is the only scatter."}{" "}
                One reel counts once. Three, four or five scatter reels award
                10, 15 or 20 free spins. Exactly two scatter reels lock for one
                respin. Cash packages always show a cash amount and are not
                scatters. The fisherman is the collector. It is not a scatter.
              </p>
              <p>
                Cash packages can form winning lines. The amounts shown on
                packages are collected only when a fisherman lands during free
                spins. Every fisherman collects every package at the multiplier
                already reached.
              </p>
              <p>
                Three, four or five scatters award 10, 15 or 20 free spins.
                Exactly two scatter reels lock for one respin. The +2 spins
                modifier adds two to the initial award and each retrigger. A
                purchased feature is already guaranteed: it shows the scatters
                and does not pay a scatter award.
              </p>
              <p>
                After each collection, fishermen advance the meter. Crossing 4,
                8 and 12 collectors awards extra spins and unlocks ×2, ×3 and
                ×10 for the next spin. No further retriggers at ×10.
              </p>
              <p>
                Ante costs 1.5× the base bet. Buy costs 100×. Chopper costs 250×
                and starts at ×2, or ×3 with the higher-start modifier.
                Purchases have no trigger scatter or base line award.
              </p>
              <p>
                Tools can rescue a mismatch: the hook shifts one recorded reel
                and brings in the fisherman, not a package. Dynamite adds
                packages. The bazooka refills around fishermen. Modifiers are
                drawn once per feature.
              </p>
              <p>
                Maximum round payout: the lower of 5,000× the base bet and
                5,000,000 LGC. At this bet: {money(cap)} LGC.
              </p>
              <details>
                <summary>Round breakdown</summary>
                <p>
                  Lines: {money(hud?.line ?? 0)} · Package collections:{" "}
                  {money(hud?.collect ?? 0)} · Scatter:{" "}
                  {money(hud?.scatter ?? 0)}. These are cumulative round
                  figures.
                </p>
              </details>
              <p className="kk-muted">
                This preview uses a local test balance. No live wallet is
                connected.
              </p>
            </div>
          </Dialog>
        ) : null}
        {buyPanel &&
          (!jurisdiction.disabledBuyFeature || !antePolicy.hidden) && (
            <Dialog
              label="Features"
              className="kk-dialog kk-purchases"
              onClose={() => setBuyPanel(false)}
            >
              <FeaturesPanel
                stake={stake}
                bank={bank}
                ante={mode === "ante"}
                anteRestriction={antePolicy}
                anteOnly={jurisdiction.disabledBuyFeature}
                locked={controlsLocked || !ready}
                onAnte={(on) => {
                  if (!busyRef.current && !jurisdiction.disabledAnte)
                    setMode(on ? "ante" : "spin");
                }}
                onStake={(next) => {
                  if (!busyRef.current && !controlsLocked) setStake(next);
                }}
                onEditBet={() => {
                  setBuyPanel(false);
                  setBetReturn("features");
                  setBetPanel(true);
                }}
                onBuy={(purchaseMode) => {
                  setBuyPanel(false);
                  if (!jurisdiction.disabledBuyFeature) void play(purchaseMode);
                }}
                onClose={() => setBuyPanel(false)}
              />
            </Dialog>
          )}
        {betPanel && (
          <Dialog
            label="Bet amount"
            className="kk-dialog kk-bet-dialog"
            onClose={closeBet}
          >
            <BetPanel
              stake={stake}
              ante={mode === "ante"}
              onClose={closeBet}
              onApply={(next) => {
                if (!busyRef.current) setStake(next);
                closeBet();
              }}
            />
          </Dialog>
        )}
        {autoPanel && !jurisdiction.disabledAutoplay && (
          <Dialog
            label="Confirm auto spins"
            className="kk-dialog kk-auto-takeover"
            rootId="kilo-auto-takeover"
            onClose={() => setAutoPanel(false)}
          >
            <AutoSpinsPanel
              count={autoCount}
              stake={stake}
              cost={cost}
              ante={mode === "ante"}
              onCount={setAutoCount}
              onClose={() => setAutoPanel(false)}
              disabled={
                controlsLocked ||
                !ready ||
                afford ||
                !splashStakeOk(stake, mode)
              }
              disabledReason={
                !ready
                  ? "Loading game"
                  : afford
                    ? "Insufficient balance"
                    : controlsLocked
                      ? "Available after this round"
                      : !splashStakeOk(stake, mode)
                        ? "Bet unavailable"
                        : undefined
              }
              onStart={() => {
                if (
                  busyRef.current ||
                  jurisdiction.disabledAutoplay ||
                  autoRunner.current?.remaining ||
                  (mode !== "spin" && mode !== "ante")
                )
                  return;
                primeAudio();
                const fixedMode = mode;
                if (autoRunner.current?.start(autoCount, () => play(fixedMode)))
