import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  ArrowLeft,
  BookOpen,
  ChevronRight,
  ChevronLeft,
  Eye,
  Minus,
  Plus,
  X,
} from "lucide-react";
import { splashCost } from "@/lib/kilo/engine";
import { STAKES, purchaseQuote, type GamePreferences } from "./control-model";

const amount = (n: number) => Math.round(n).toLocaleString("en-US");
import {
  FEATURES,
  FEATURE_GROUPS,
  featuresForGroup,
  type BonusFeature,
  type FeatureGroup,
} from "./feature-catalog";
import "./feature-panel.css";

type ArtworkStatus = "ready" | "error";
const artworkStatus = new Map<string, ArtworkStatus>();
const artworkLoads = new Map<string, Promise<void>>();
let artworkPreload: Promise<void> | null = null;

function decodeFeatureArtwork(src: string): Promise<void> {
  if (typeof Image === "undefined") return Promise.resolve();
  const existing = artworkLoads.get(src);
  if (existing) return existing;
  const pending = new Promise<void>((resolve) => {
    const image = new Image();
    let finished = false;
    const finish = (status: ArtworkStatus) => {
      if (finished) return;
      finished = true;
      window.clearTimeout(timeout);
      artworkStatus.set(src, status);
      resolve();
    };
    // A failed or stalled image must not leave an unusable loading panel.
    const timeout = window.setTimeout(() => finish("error"), 12000);
    image.decoding = "async";
    image.fetchPriority = "low";
    image.onload = () => {
      image.decode().then(
        () => finish("ready"),
        () => finish(image.naturalWidth > 0 ? "ready" : "error"),
      );
    };
    image.onerror = () => finish("error");
    image.src = src;
  });
  artworkLoads.set(src, pending);
  return pending;
}

/** Warm and decode the existing artwork while the game enters, once per page. */
export function preloadFeatureArtwork(): Promise<void> {
  artworkPreload ??= Promise.all(
    FEATURES.map((feature) => decodeFeatureArtwork(feature.art)),
  ).then(() => undefined);
  return artworkPreload;
}

function FeatureImage({
  feature,
  className = "",
}: {
  feature: BonusFeature;
  className?: string;
}) {
  const [status, setStatus] = useState<ArtworkStatus | "loading">(
    artworkStatus.get(feature.art) ?? "loading",
  );
  useEffect(() => {
    let current = true;
    void decodeFeatureArtwork(feature.art).then(() => {
      if (current) setStatus(artworkStatus.get(feature.art) ?? "error");
    });
    return () => {
      current = false;
    };
  }, [feature.art]);
  return (
    <div className={`kk-feature-image ${className}`} data-art-status={status}>
      <img
        src={feature.art}
        alt=""
        width="1536"
        height="1024"
        decoding="async"
        onLoad={() => setStatus("ready")}
        onError={() => setStatus("error")}
      />
      {status !== "ready" && (
        <span className="kk-art-fallback">
          {status === "loading" ? "Loading artwork" : "Artwork unavailable"}
        </span>
      )}
    </div>
  );
}

/** Dialog owns the dismissal timing; panels keep their normal close fallback. */
export const PanelDismissContext = createContext<(() => void) | null>(null);

export function PanelHeader({
  title,
  onClose,
  onBack,
}: {
  title: string;
  onClose: () => void;
  onBack?: () => void;
}) {
  const dismiss = useContext(PanelDismissContext) ?? onClose;
  return (
    <div className="kk-dialog-head">
      {onBack && (
        <button
          type="button"
          className="kk-icon-button"
          aria-label="Back"
          onClick={onBack}
        >
          <ArrowLeft size={20} />
        </button>
      )}
      <strong>{title}</strong>
      <button
        type="button"
        className="kk-icon-button"
        aria-label="Close"
        onClick={dismiss}
      >
        <X size={21} />
      </button>
    </div>
  );
}

export function BetPanel({
  stake,
  ante,
  onApply,
  onClose,
}: {
  stake: number;
  ante: boolean;
  onApply: (n: number) => void;
  onClose: () => void;
}) {
  const [draft, setDraft] = useState(stake);
  const index = STAKES.findIndex((n) => n === draft);
  return (
    <>
      <PanelHeader title="Bet amount" onClose={onClose} />
      <div className="kk-dialog-body kk-bet-panel">
        <span className="kk-field-label">Base bet · LGC</span>
        <div className="kk-bet-adjust">
          <button
            type="button"
            className="kk-icon-button"
            aria-label="Decrease bet"
            disabled={index <= 0}
            onClick={() => setDraft(STAKES[index - 1]!)}
          >
            <Minus size={21} />
          </button>
          <output
            className="kk-bet-value-display"
            key={draft}
            aria-live="polite"
          >
            <b>{amount(draft)}</b>
            <small>LGC</small>
          </output>
          <button
            type="button"
            className="kk-icon-button"
            aria-label="Increase bet"
            disabled={index >= STAKES.length - 1}
            onClick={() => setDraft(STAKES[index + 1]!)}
          >
            <Plus size={21} />
          </button>
        </div>
        <div
          className="kk-denominations"
          role="group"
          aria-label="Base bet amounts"
        >
          {STAKES.map((n) => (
            <button
              key={n}
              type="button"
              aria-pressed={n === draft}
              onClick={() => setDraft(n)}
            >
              {amount(n)}
            </button>
          ))}
        </div>
        <div className="kk-cost-line">
          <span>{ante ? "Per spin · Ante on" : "Per spin"}</span>
          <b>
            {amount(splashCost(draft, ante ? "ante" : "spin"))}{" "}
            <small>LGC</small>
          </b>
        </div>
      </div>
      <div className="kk-dialog-foot">
        <button
          type="button"
          className="kk-primary"
          onClick={() => onApply(draft)}
        >
          Apply bet
        </button>
      </div>
    </>
  );
}

function ScatterMarks({ count }: { count: number }) {
  return (
    <span className="kk-scatter-marks" aria-label={`${count} scatters`}>
      {Array.from({ length: count }, (_, i) => (
        <img
          key={i}
          src="/kilo-contraband-v1/scatter-king.png"
          alt=""
          aria-hidden="true"
        />
      ))}
    </span>
  );
}

/** The entry composition is also the art preview; it never starts a round. */
export function BonusArtwork({ feature }: { feature: BonusFeature }) {
  return (
    <div className="kk-bonus-artwork" data-tone={feature.tone}>
      <FeatureImage feature={feature} />
      <div className="kk-bonus-artwork-copy">
        <span className="kk-art-kicker">
          {feature.kind === "preview" ? "Artwork preview" : feature.subtitle}
        </span>
        <h2>{feature.title}</h2>
        {feature.kind !== "preview" && feature.scatters && (
          <ScatterMarks count={feature.scatters} />
        )}
        {feature.kind !== "preview" ? (
          <div className="kk-art-award">
            <b>{feature.spins}</b>
            <span>
              free spins<small>Starts at ×{feature.multiplier}</small>
            </span>
          </div>
        ) : (
          <span className="kk-art-development">In development</span>
        )}
      </div>
    </div>
  );
}

export function FeatureCard({
  feature,
  stake,
  bank,
  locked,
  onSelect,
}: {
  feature: BonusFeature;
  stake: number;
  bank: number;
  locked: boolean;
  onSelect: (feature: BonusFeature) => void;
}) {
  const q =
    feature.kind === "purchase"
      ? purchaseQuote(stake, feature.mode, bank)
      : null;
  return (
    <article
      className="kk-feature-card"
      key={feature.id}
      data-feature={feature.id}
      data-tone={feature.tone}
      tabIndex={-1}
      aria-label={feature.title}
    >
      <div className="kk-feature-hero">
        <FeatureImage feature={feature} className="kk-feature-illustration" />
        <div className="kk-feature-card-head">
          <span className="kk-feature-kind">
            {feature.kind === "purchase"
              ? "Bonus buy"
              : feature.kind === "trigger"
                ? "Scatter bonus"
                : "In development"}
          </span>
          <h2>{feature.title}</h2>
        </div>
      </div>
      <div className="kk-feature-card-copy">
        <div className="kk-feature-reward">
          {feature.kind === "preview" ? (
            <span>Artwork & design preview</span>
          ) : (
            <>
              <b>
                <strong>{feature.spins}</strong> free spins
              </b>
              <span>Starts at ×{feature.multiplier}</span>
            </>
          )}
        </div>
        <div className="kk-feature-offer" data-purchase={!!q}>
          {q ? (
            <>
              <span className="kk-feature-price-label">Purchase price</span>
              <b>
                {amount(q.cost)} <small>LGC</small>
              </b>
              <span>
                {feature.kind === "purchase" ? feature.multiple : ""}× base bet
              </span>
            </>
          ) : feature.kind === "trigger" ? (
            <>
              <ScatterMarks count={feature.scatters} />
              <span>Land {feature.scatters} scatters</span>
            </>
          ) : (
            <>
              <Eye size={22} aria-hidden="true" />
              <span>Gameplay in development</span>
            </>
          )}
        </div>
        <div className="kk-feature-decision" data-unavailable={!!q?.reason}>
          <button
            type="button"
            className={
              q ? "kk-feature-action is-purchase" : "kk-feature-action"
            }
            aria-label={
              q
                ? `Review ${feature.title} purchase for ${amount(q.cost)} LGC`
                : `Preview ${feature.title}`
            }
            disabled={!!q && (locked || !q.allowed)}
            aria-describedby={
              q?.reason ? `feature-${feature.id}-reason` : undefined
            }
            onClick={() => onSelect(feature)}
          >
            {q ? "Buy feature" : "View preview"}
            <ChevronRight size={17} />
          </button>
          <div
            className="kk-feature-availability"
            data-unavailable={!!q?.reason}
          >
            {q?.reason && (
              <p
                id={`feature-${feature.id}-reason`}
                className="kk-unavailable"
                role="status"
              >
                {q.reason}
              </p>
            )}
          </div>
        </div>
      </div>
    </article>
  );
}

export function FeaturesPanel({
  stake,
  bank,
  ante,
  anteRestriction = { hidden: false, disabled: false },
  anteOnly = false,
  locked,
  onAnte,
  onEditBet,
  onStake,
  onBuy,
  onClose,
}: {
  stake: number;
  bank: number;
  ante: boolean;
  anteRestriction?: { hidden: boolean; disabled: boolean; reason?: string };
  anteOnly?: boolean;
  locked: boolean;
  onAnte: (on: boolean) => void;
  onEditBet: () => void;
  onStake: (stake: number) => void;
  onBuy: (mode: "buy" | "chopper") => void;
  onClose: () => void;
}) {
  const [choice, setChoice] = useState<BonusFeature | null>(null);
  const [group, setGroup] = useState<FeatureGroup>("buy");
  const [readyGroup, setReadyGroup] = useState<FeatureGroup | null>(null);
  const [active, setActive] = useState(0);
  const submitted = useRef(false);
  const gallery = useRef<HTMLDivElement>(null);
  const detail = useRef<HTMLDivElement>(null);
  const lastChoice = useRef<string | null>(null);
  const visibleFeatures = featuresForGroup(group);
  const artworkReady =
    readyGroup === group ||
    visibleFeatures.every((feature) => artworkStatus.has(feature.art));
  const quote =
    choice?.kind === "purchase"
      ? purchaseQuote(stake, choice.mode, bank)
      : null;

  useEffect(() => {
    void preloadFeatureArtwork();
  }, []);
  useEffect(() => {
    let current = true;
    void Promise.all(
      visibleFeatures.map((feature) => decodeFeatureArtwork(feature.art)),
    ).then(() => {
      if (current) setReadyGroup(group);
    });
    return () => {
      current = false;
    };
  }, [group]);

  useEffect(() => {
    if (choice) {
      detail.current?.focus({ preventScroll: true });
      return;
    }
    const root = gallery.current;
    if (!root) return;
    if (lastChoice.current) {
      const index = visibleFeatures.findIndex(
        (feature) => feature.id === lastChoice.current,
      );
      if (index >= 0) showCard(index, true);
    }
    // Rotation can remove the overflow without emitting a scroll event.
    // Keep the phone pager tied to the visible card after either breakpoint.
    const observer = new ResizeObserver(() => {
      const first = root.children[0] as HTMLElement | undefined;
      const next = root.children[1] as HTMLElement | undefined;
      const step = first && next ? next.offsetLeft - first.offsetLeft : 0;
      setActive(
        root.scrollWidth > root.clientWidth + 1 && step > 0
          ? Math.min(
              visibleFeatures.length - 1,
              Math.max(0, Math.round(root.scrollLeft / step)),
            )
          : 0,
      );
    });
    observer.observe(root);
    return () => observer.disconnect();
  }, [choice, group, artworkReady]);

  const changeGroup = (next: FeatureGroup) => {
    setGroup(next);
    setActive(0);
    lastChoice.current = null;
  };

  const showCard = (index: number, focusCard = false) => {
    const root = gallery.current;
    const card = root?.children[index] as HTMLElement | undefined;
    const first = root?.children[0] as HTMLElement | undefined;
    if (root && card && first)
      root.scrollTo({ left: card.offsetLeft - first.offsetLeft });
    setActive(index);
    if (focusCard && card) {
      // Arrow navigation changes both the visible offer and keyboard target.
      // A disabled offer receives focus on its article, never its old neighbor.
      const button = card.querySelector<HTMLButtonElement>(
        "button:not(:disabled)",
      );
      (button ?? card).focus({ preventScroll: true });
    }
  };
  const select = (feature: BonusFeature) => {
    lastChoice.current = feature.id;
    submitted.current = false;
    setChoice(feature);
  };

  return (
    <>
      <PanelHeader
        title={
          choice
            ? choice.kind === "purchase"
              ? "Confirm purchase"
              : "Bonus preview"
            : "Features"
        }
        onClose={onClose}
        onBack={choice ? () => setChoice(null) : undefined}
      />
      <div
        key={choice?.id ?? "gallery"}
        data-view={choice ? "detail" : "gallery"}
        className={`kk-dialog-body kk-features-body${choice ? " is-detail" : ""}`}
      >
        {choice?.kind === "purchase" && quote ? (
          <div
            className="kk-purchase-confirmation"
            ref={detail}
            tabIndex={-1}
            data-testid="purchase-confirmation"
            data-tone={choice.tone}
          >
            <FeatureImage feature={choice} className="kk-confirm-art" />
            <h2>{choice.title}</h2>
            <p className="kk-confirm-award">
              {choice.spins} free spins · Starts at ×{choice.multiplier}
            </p>
            <div className="kk-confirm-cost">
              <span>Purchase cost</span>
              <strong>{amount(quote.cost)}</strong>
              <small>LGC</small>
            </div>
            <dl className="kk-confirm-wallet">
              <div>
                <dt>Base bet</dt>
                <dd>{amount(stake)} LGC</dd>
              </div>
              <div>
                <dt>Balance</dt>
                <dd>{amount(bank)} LGC</dd>
              </div>
            </dl>
            <p className="kk-muted">
              The bonus modifier may increase the starting award.
              <br />
              Charged once when you confirm.
            </p>
            {quote.reason && (
              <p className="kk-unavailable" role="status">
                {quote.reason}
              </p>
            )}
          </div>
        ) : choice ? (
          <div
            className="kk-feature-detail"
            ref={detail}
            tabIndex={-1}
            data-testid="bonus-art-preview"
          >
            <BonusArtwork feature={choice} />
            <div className="kk-feature-detail-copy">
              <span className="kk-field-label">
                {choice.kind === "trigger" ? "Scatter bonus" : "Design preview"}
              </span>
              <h2>{choice.title}</h2>
              <p>{choice.detail}</p>
              <p className="kk-preview-note">
                <Eye size={17} aria-hidden="true" />
                Preview only · No bet is placed.
              </p>
            </div>
          </div>
        ) : (
          <>
            {!anteOnly && (
              <>
                <div
                  className="kk-feature-tabs"
                  role="tablist"
                  aria-label="Feature categories"
                >
                  {FEATURE_GROUPS.map((item) => (
                    <button
                      key={item.id}
                      id={`feature-tab-${item.id}`}
                      type="button"
                      role="tab"
                      aria-selected={group === item.id}
                      aria-controls="feature-gallery-panel"
                      tabIndex={group === item.id ? 0 : -1}
                      onClick={() => changeGroup(item.id)}
                      onKeyDown={(event) => {
                        const index = FEATURE_GROUPS.findIndex(
                          (entry) => entry.id === group,
                        );
                        const next =
                          event.key === "ArrowRight"
                            ? (index + 1) % FEATURE_GROUPS.length
                            : event.key === "ArrowLeft"
                              ? (index + FEATURE_GROUPS.length - 1) %
                                FEATURE_GROUPS.length
                              : event.key === "Home"
                                ? 0
                                : event.key === "End"
                                  ? FEATURE_GROUPS.length - 1
                                  : -1;
                        if (next < 0) return;
                        event.preventDefault();
                        const target = FEATURE_GROUPS[next]!;
                        changeGroup(target.id);
                        event.currentTarget.parentElement
                          ?.querySelector<HTMLButtonElement>(
                            `#feature-tab-${target.id}`,
                          )
                          ?.focus();
                      }}
                    >
                      {item.title}
                    </button>
                  ))}
                </div>
                <section
                  id="feature-gallery-panel"
                  role="tabpanel"
                  aria-labelledby={`feature-tab-${group}`}
                  aria-busy={!artworkReady}
                  className="kk-feature-group"
                  data-group={group}
                >
                  {!artworkReady ? (
                    <div className="kk-feature-loading" role="status">
                      <span className="kk-art-loader" aria-hidden="true" />
                      <strong>Loading features</strong>
                      <span>Preparing the artwork</span>
                    </div>
                  ) : (
                    <>
                      <div
                        className="kk-feature-gallery"
                        key={group}
                        data-count={visibleFeatures.length}
                        ref={gallery}
                        aria-label="Bonus features"
                        onKeyDown={(event) => {
                          const root = gallery.current;
                          if (!root || root.scrollWidth <= root.clientWidth + 1)
                            return;
                          if (
                            event.key !== "ArrowRight" &&
                            event.key !== "ArrowLeft"
                          )
                            return;
                          event.preventDefault();
                          showCard(
                            Math.max(
                              0,
                              Math.min(
                                visibleFeatures.length - 1,
                                active + (event.key === "ArrowRight" ? 1 : -1),
                              ),
                            ),
                            true,
                          );
                        }}
                        onScroll={() => {
                          const root = gallery.current;
                          if (!root || root.scrollWidth <= root.clientWidth + 1)
                            return;
                          const first = root.children[0] as HTMLElement;
                          const next = root.children[1] as HTMLElement;
                          const step = next.offsetLeft - first.offsetLeft;
                          if (step > 0)
                            setActive(
                              Math.min(
                                visibleFeatures.length - 1,
                                Math.max(0, Math.round(root.scrollLeft / step)),
                              ),
                            );
                        }}
                      >
                        {visibleFeatures.map((feature) => (
                          <FeatureCard
                            key={feature.id}
                            feature={feature}
                            stake={stake}
                            bank={bank}
                            locked={locked}
                            onSelect={select}
                          />
                        ))}
                      </div>
                      <nav
                        className="kk-feature-pager"
                        aria-label="Browse bonuses"
                      >
                        <button
                          type="button"
                          className="kk-icon-button"
                          aria-label="Previous bonus"
                          disabled={active === 0}
                          onClick={() => showCard(active - 1)}
                        >
                          <ChevronLeft size={20} />
                        </button>
                        <div className="kk-feature-pagination">
                          <div className="kk-feature-dots" aria-hidden="true">
                            {visibleFeatures.map((feature, i) => (
                              <span
                                key={feature.id}
                                data-active={i === active ? "true" : undefined}
                              />
                            ))}
                          </div>
                          <span aria-live="polite">
                            {active + 1} / {visibleFeatures.length}
                          </span>
                        </div>
                        <button
                          type="button"
                          className="kk-icon-button"
                          aria-label="Next bonus"
                          disabled={active === visibleFeatures.length - 1}
                          onClick={() => showCard(active + 1)}
                        >
                          <ChevronRight size={20} />
                        </button>
                      </nav>
                    </>
                  )}
                </section>
              </>
            )}
            <div className="kk-feature-utilities">
              {!anteRestriction.hidden && (
                <div
                  className="kk-ante-feature"
                  data-active={ante ? "true" : undefined}
                >
                  <div className="kk-ante-copy">
                    <h2>Ante bet</h2>
                    <p>
                      1.5× base bet · {amount(splashCost(stake, "ante"))} LGC /
                      spin
                    </p>
                  </div>
                  <button
                    type="button"
                    className="kk-ante-action"
                    aria-pressed={ante}
                    aria-label={
                      ante ? "Deactivate ante bet" : "Activate ante bet"
                    }
                    disabled={locked || anteRestriction.disabled}
                    title={anteRestriction.reason}
                    onClick={() => {
                      if (!anteRestriction.disabled) onAnte(!ante);
                    }}
                  >
                    <span className="kk-ante-switch" aria-hidden="true" />
                    {ante ? "Ante On" : "Ante Off"}
                  </button>
                </div>
              )}
              <div className="kk-feature-toolbar">
                <div className="kk-feature-balance">
                  <span>Balance</span>
                  <b>
                    {amount(bank)} <small>LGC</small>
                  </b>
                </div>
                <div
                  className="kk-feature-bet-control"
                  aria-label="Feature base bet"
                >
                  <button
                    type="button"
                    className="kk-icon-button"
                    aria-label="Decrease feature base bet"
                    disabled={locked || stake === STAKES[0]}
                    onClick={() =>
                      onStake(
                        STAKES[
                          Math.max(0, STAKES.findIndex((n) => n === stake) - 1)
                        ]!,
                      )
                    }
                  >
                    <Minus size={18} />
                  </button>
                  <button
                    type="button"
                    className="kk-feature-bet"
                    onClick={onEditBet}
                    disabled={locked}
                  >
                    <span>Base bet</span>
                    <b>
                      {amount(stake)} <small>LGC</small>
                    </b>
                  </button>
                  <button
                    type="button"
                    className="kk-icon-button"
                    aria-label="Increase feature base bet"
                    disabled={locked || stake === STAKES.at(-1)}
                    onClick={() =>
                      onStake(
                        STAKES[
                          Math.min(
                            STAKES.length - 1,
                            STAKES.findIndex((n) => n === stake) + 1,
                          )
                        ]!,
                      )
                    }
                  >
                    <Plus size={18} />
                  </button>
                </div>
              </div>
            </div>
            <p className="kk-gallery-note">
              {anteOnly
                ? "Ante changes the cost of each spin. Your next spin uses the selected wager."
                : "Purchases require confirmation. Preview cards place no bet."}
            </p>
          </>
        )}
      </div>
      {choice && (
        <div className="kk-dialog-foot kk-confirm-actions">
          <button
            type="button"
            className="kk-secondary"
            onClick={() => setChoice(null)}
          >
            {choice.kind === "purchase" ? "Back" : "Back to features"}
          </button>
          {choice.kind === "purchase" && quote && (
            <button
              type="button"
              className="kk-primary"
              data-testid="confirm-purchase"
              disabled={locked || !quote.allowed}
              onClick={() => {
                if (submitted.current || locked || !quote.allowed) return;
                submitted.current = true;
                onBuy(choice.mode);
              }}
            >
              Buy · {amount(quote.cost)} LGC
            </button>
          )}
        </div>
      )}
    </>
  );
}

export function SettingsPanel({
  compactActions,
  disabledTurbo = false,
  preferences,
  onChange,
  locked,
  onRules,
  onClose,
  onBack,
}: {
  compactActions?: ReactNode;
  disabledTurbo?: boolean;
  preferences: GamePreferences;
  onChange: (p: GamePreferences) => void;
  locked: boolean;
  onRules: () => void;
  onClose: () => void;
  onBack: () => void;
}) {
  return (
    <>
      <PanelHeader title="Game settings" onClose={onClose} onBack={onBack} />
      <div className="kk-dialog-body kk-settings-body">
        {compactActions}
        <fieldset disabled={locked}>
          <legend>Spin speed</legend>
          <div className="kk-segmented">
            {(
              [
                ["normal", "Normal"],
                ["turbo", "Turbo"],
                ["super", "Super turbo"],
              ] as const
            ).map(([value, label]) => (
              <button
                type="button"
                key={value}
                disabled={disabledTurbo && value !== "normal"}
                aria-pressed={preferences.speed === value}
                onClick={() => onChange({ ...preferences, speed: value })}
              >
                {label}
              </button>
            ))}
          </div>
          <p className="kk-setting-hint">
            {disabledTurbo
              ? "Turbo speeds are unavailable in this jurisdiction."
              : locked
                ? "Available after this round."
                : "Faster reels. Feature results remain readable."}
          </p>
        </fieldset>
        <fieldset disabled={locked}>
          <legend>Reduced motion</legend>
          <div className="kk-segmented">
            {(
              [
                ["system", "System"],
                ["reduce", "On"],
                ["full", "Off"],
              ] as const
            ).map(([value, label]) => (
              <button
                type="button"
                key={value}
                aria-pressed={preferences.motion === value}
                onClick={() => onChange({ ...preferences, motion: value })}
              >
                {label}
              </button>
            ))}
          </div>
          <p className="kk-setting-hint">
            Limits reel motion, count-ups and decorative effects.
          </p>
        </fieldset>
        <button type="button" className="kk-menu-link" onClick={onRules}>
          <BookOpen size={20} />
          <span>Rules & paytable</span>
          <ChevronRight size={18} />
        </button>
      </div>
    </>
  );
}

sources.src/components/slot-controls/SlotControl:
import { useId, type CSSProperties, type ReactNode, type Ref } from "react";
import {
  Zap,
  Menu,
  RefreshCw,
  SkipForward,
  Square,
  ChevronDown,
  ChevronUp,
  Gem,
  LockKeyhole,
  X,
} from "lucide-react";
import {
  controlPlacement as place,
  type ControlLayout,
  type ControlRect,
} from "./layout";
import {
  controlAvailability,
  controlThemeStyle,
  CONTROL_TOKENS,
  DEFAULT_CONTROL_THEME,
  type ControlJurisdiction,
  type ControlTheme,
} from "./tokens";
import {
  controlReadoutTextStyle,
  controlReadoutOverflows,
  controlBetInset,
} from "./typography";
import "./controls.css";

export type ControlIcons = Partial<
  Record<
    | "turbo"
    | "menu"
    | "auto"
    | "spin"
    | "skip"
    | "stop"
    | "buy"
    | "minus"
    | "plus"
    | "locked"
    | "close",
    ReactNode
  >
>;
const DEFAULT_ICONS: Required<ControlIcons> = {
  turbo: <Zap />,
  menu: <Menu />,
  auto: <RefreshCw />,
  spin: (
    <svg
      className="sc-spin-arrow"
      viewBox="0 0 32 32"
      fill="none"
      aria-hidden="true"
    >
      <path
        d="M19.5 25.4A10 10 0 1 1 26 16"
        stroke="currentColor"
        strokeLinecap="round"
      />
      <path d="M20.5 15.5 26 22 31.5 15.5Z" fill="currentColor" stroke="none" />
    </svg>
  ),
  skip: <SkipForward />,
  stop: <Square />,
  buy: <Gem />,
  minus: <ChevronDown />,
  plus: <ChevronUp />,
  locked: <LockKeyhole />,
  close: <X />,
};
export type SlotControlState = {
  balance: string;
  win: string;
  bet: string;
  /** Actual per-spin wager when Ante is active; supplied by the host. */
  wager?: string;
  currency: string;
  ante: boolean;
  speed: "normal" | "turbo" | "super";
  menuOpen?: boolean;
  feature?: { remaining: number; multiplier: number };
  busy: boolean;
  autoRemaining: number;
  ready: boolean;
  locked: boolean;
  spinDisabled: boolean;
  /** Host-owned explanation; exposed accessibly without text on the Spin face. */
  spinDisabledReason?: string;
  minimumBet: boolean;
  maximumBet: boolean;
  charge: { amount: string } | { label: string };
  awardLanded?: boolean;
  reducedMotion?: boolean;
};
export type SlotControlActions = {
  menu: () => void;
  turbo: () => void;
  bet: () => void;
  minus: () => void;
  plus: () => void;
  auto: () => void;
  spin: () => void;
  buy: () => void;
};
export type SlotControlsProps = {
  layout: ControlLayout;
  state: SlotControlState;
  actions: SlotControlActions;
  theme?: ControlTheme;
  icons?: ControlIcons;
  jurisdiction?: ControlJurisdiction;
  spinRef?: Ref<HTMLButtonElement>;
  menuRef?: Ref<HTMLButtonElement>;
  menuPopupId?: string;
  /** Optional integration anchors for a host's win-flight renderer. */
  bonusAnchorClassName?: string;
};

export function SlotControls({
  layout: d,
  state: s,
  actions: a,
  theme = DEFAULT_CONTROL_THEME,
  icons,
  jurisdiction,
  spinRef,
  menuRef,
  menuPopupId,
  bonusAnchorClassName = "",
}: SlotControlsProps) {
  const chargeId = useId(),
    reasonId = useId(),
    icon = { ...DEFAULT_ICONS, ...icons };
  const speedName =
    s.speed === "super"
      ? "Super turbo"
      : s.speed === "turbo"
        ? "Turbo"
        : "Normal";
  function restrictionReason(
    message: string | undefined,
    id: string,
    r: ControlRect,
  ) {
    if (!message) return null;
    const width = Math.min(CONTROL_TOKENS.reasonWidth, d.width);
    return (
      <span
        className="sc-control-reason"
        id={id}
        role="tooltip"
        style={{
          width,
          left:
            Math.max(0, Math.min(r.x + r.w / 2 - width / 2, d.width - width)) -
            r.x,
          ...(r.y < 80
            ? { top: `calc(100% + ${CONTROL_TOKENS.gap}px)` }
            : { bottom: `calc(100% + ${CONTROL_TOKENS.gap}px)` }),
        }}
      >
        {message}
      </span>
    );
  }
  function circle(key: "turbo" | "menu" | "auto" | "buy", r: ControlRect) {
    const restriction =
      key === "menu"
        ? { hidden: false, disabled: false, reason: undefined }
        : controlAvailability(key, jurisdiction);
    if (
      !r.w ||
      restriction.hidden ||
      (s.feature && (key === "auto" || key === "buy"))
    )
      return null;
    const foldedSpeed =
      key === "menu" &&
      d.drawer.turbo &&
      !controlAvailability("turbo", jurisdiction).disabled;
    const label =
      key === "menu"
        ? s.menuOpen
          ? "Close game menu"
          : `Game menu: info, music and sound${foldedSpeed ? `. Spin speed: ${speedName}` : ""}`
        : key === "turbo"
          ? `Spin speed: ${speedName}. Change speed`
          : key === "buy"
            ? "Buy feature"
            : s.autoRemaining
              ? `Stop auto spins, ${s.autoRemaining} remaining`
              : "Auto spins: choose a finite count";
    const disabled =
      restriction.disabled ||
      (key === "menu"
        ? false
        : key === "auto" && s.autoRemaining
          ? false
          : s.locked || !s.ready);
    return (
      <button
        type="button"
        key={key}
        ref={key === "menu" ? menuRef : undefined}
        className={`sc-button sc-circle${key === "auto" ? " sc-auto-joined" : ""}`}
        data-control={key}
        data-captioned={key === "buy" || undefined}
        style={place(r)}
        data-focus-fallback={key === "menu" || undefined}
        aria-label={label}
        aria-expanded={key === "menu" ? !!s.menuOpen : undefined}
        aria-controls={key === "menu" ? menuPopupId : undefined}
        title={restriction.disabled ? undefined : label}
        aria-haspopup={
          key === "menu" ||
          key === "buy" ||
          (key === "auto" && !s.autoRemaining)
            ? "dialog"
            : undefined
        }
        aria-pressed={
          key === "turbo"
            ? s.speed !== "normal"
            : key === "auto"
              ? s.autoRemaining > 0
              : undefined
        }
        aria-disabled={restriction.disabled || undefined}
        aria-describedby={restriction.reason ? `${reasonId}-${key}` : undefined}
        disabled={disabled && !restriction.disabled}
        onClick={(event) => {
          if (disabled) {
            if (restriction.disabled) event.currentTarget.focus();
            return;
          }
          a[key]();
        }}
      >
        <span className="sc-icon" aria-hidden="true">
          {key === "menu" && s.menuOpen
            ? icon.close
            : key === "auto" && s.autoRemaining
              ? icon.stop
              : icon[key]}
        </span>
        {key === "auto" && !s.autoRemaining && (
          <span className="sc-auto-letter" aria-hidden="true">
            A
          </span>
        )}
        {key === "buy" && (
          <span className="sc-control-caption" aria-hidden="true">
            Buy
          </span>
        )}
        {(key === "turbo" || foldedSpeed) && !restriction.disabled && (
          <b
            className={`sc-badge${foldedSpeed ? " sc-badge-speed" : ""}`}
            data-active={s.speed !== "normal"}
            aria-hidden="true"
          >
            {foldedSpeed && <span className="sc-icon">{icon.turbo}</span>}
            {s.speed === "super" ? "3" : s.speed === "turbo" ? "2" : "1"}
          </b>
        )}
        {key === "auto" && s.autoRemaining > 0 && (
          <b className="sc-badge">{s.autoRemaining}</b>
        )}
        {restriction.disabled && (
          <span className="sc-restriction-mark" aria-hidden="true">
            {icon.locked}
          </span>
        )}
        {restrictionReason(restriction.reason, `${reasonId}-${key}`, r)}
      </button>
    );
  }
  const readoutSize =
    d.variant === "desktop" ? 22 : d.variant === "compact" ? 18 : 20;
  const readoutLineHeight = d.variant === "desktop" ? 26 : 23;
  const betSize =
    d.variant === "compact" || d.betButton.w < 64
      ? 18
      : d.variant === "desktop"
        ? 22
        : 20;
  const betLineHeight = d.variant === "desktop" ? 26 : 23;
  const betValue = s.wager ?? s.bet;
  const betInset = controlBetInset(betValue, d.betButton.w, betSize);
  const readoutCard = {
    x: Math.min(d.balance.x, d.win.x),
    y: Math.min(d.balance.y, d.win.y),
    w:
      Math.max(d.balance.x + d.balance.w, d.win.x + d.win.w) -
      Math.min(d.balance.x, d.win.x),
    h:
      Math.max(d.balance.y + d.balance.h, d.win.y + d.win.h) -
      Math.min(d.balance.y, d.win.y),
  };
  const well = (name: "balance" | "win", value: string, r: ControlRect) => (
    <div
      className={`sc-well sc-readout${name === "win" && s.feature ? ` ${bonusAnchorClassName}` : ""}`}
      data-module={name}
      data-landed={(name === "win" && s.awardLanded) || undefined}
      style={place(r)}
    >
      <span className="sc-label">
        {name === "balance" ? "Balance" : s.feature ? "Bonus win" : "Win"}
      </span>
      <strong
        data-testid={
          name === "balance" ? "balance" : s.feature ? "bonus-win" : "last-win"
        }
        className="sc-number"
        style={{
          ...controlReadoutTextStyle(
            value,
            r.w - 20,
            readoutSize,
            readoutLineHeight,
          ),
          width: r.w - (d.variant === "compact" ? 8 : 20),
        }}
      >
        {controlReadoutOverflows(
          value,
          r.w - (d.variant === "compact" ? 8 : 20),
          readoutSize,
        ) ? (
          <>
            <span className="sc-sr-only" aria-hidden="true">
              {value}
            </span>
            <input
              className="sc-overflow-amount"
              type="text"
              readOnly
              value={value}
              aria-label={`${name === "balance" ? "Balance" : s.feature ? "Bonus win" : "Win"}, ${s.currency}`}
              title={`${value} ${s.currency}. Full amount: use arrow keys or select the text to read across.`}
            />
          </>
        ) : (
          value
        )}
      </strong>
    </div>
  );
  const primary = s.autoRemaining ? "stop" : s.busy ? "skip" : "spin";
  const disabledReason = s.spinDisabled ? s.spinDisabledReason : undefined;
  return (
    <aside
      className="sc-system"
      data-variant={d.variant}
      data-feature={!!s.feature}
      data-reduced={!!s.reducedMotion}
      aria-label="Game controls"
      data-testid="control-bar"
      style={
        {
          ...controlThemeStyle(theme),
          width: d.width,
          height: d.height,
        } as CSSProperties
      }
    >
      <div role="group" aria-label="Utilities" className="sc-module-group">
        {circle("turbo", s.feature ? d.featureTurbo : d.turbo)}
        {circle("menu", s.feature ? d.featureMenu : d.menu)}
      </div>
      <div
        role="group"
        aria-label="Balance and win"
        className="sc-module-group"
      >
        <div
          className="sc-well sc-readout-card"
          data-module="readouts"
          aria-hidden="true"
          style={place(readoutCard)}
        />
        {well("balance", s.balance, d.balance)}
        {well("win", s.win, d.win)}
      </div>
      {s.feature ? (
        <div
          className="sc-well sc-feature-counter"
          data-module="free-spins"
          style={place(d.counter)}
        >
          <span className="sc-label">Free spins</span>
          <strong>
            {s.feature.remaining}
            <small>left</small>
            <em>×{s.feature.multiplier}</em>
          </strong>
        </div>
      ) : (
        <div
          className="sc-well sc-bet"
          data-module="bet"
          role="group"
          aria-label="Bet controls"
          style={place(d.bet)}
        >
          <button
            type="button"
            className="sc-button sc-bet-value"
            style={{ ...place(d.betButton), paddingLeft: betInset }}
            disabled={s.locked}
            onClick={a.bet}
            aria-label={`Change base bet, ${s.bet} ${s.currency}${s.ante ? ", Ante On" : ""}`}
            aria-haspopup="dialog"
          >
            <span className="sc-label">Bet</span>
            <strong
              className="sc-number sc-bet-number"
              data-testid="bet-readout"
              title={`Base bet ${s.bet}${s.ante ? `. Ante On; per spin ${betValue}` : ""}`}
              style={{
                ...controlReadoutTextStyle(
                  betValue,
                  d.betButton.w,
                  betSize,
                  betLineHeight,
                ),
                maxWidth: d.betButton.w - betInset,
              }}
            >
              {betValue}
            </strong>
          </button>
          {(["minus", "plus"] as const).map(
            (key) =>
              d[key].w > 0 && (
                <button
                  key={key}
                  type="button"
                  className="sc-button sc-step"
                  style={place(d[key])}
                  aria-label={`${key === "minus" ? "Decrease" : "Increase"} base bet`}
                  disabled={
                    s.locked || (key === "minus" ? s.minimumBet : s.maximumBet)
                  }
                  onClick={a[key]}
                >
                  <span className="sc-icon" aria-hidden="true">
                    {icon[key]}
                  </span>
                </button>
              ),
          )}
        </div>
      )}
      <div role="group" aria-label="Play actions" className="sc-module-group">
        {!s.feature &&
          d.actionPlate.w > 0 &&
          !controlAvailability("auto", jurisdiction).hidden && (
            <div
              className="sc-well sc-action-plate"
              data-join={d.actionJoin}
              aria-hidden="true"
              style={place(d.actionPlate)}
            />
          )}
        {circle("auto", d.auto)}
        <div
          className="sc-spin-group"
          data-module="action"
          style={place(d.spin)}
        >
          <button
            type="button"
            className="sc-button sc-spin"
            ref={spinRef}
            data-testid="spin-button"
            aria-describedby={`${chargeId}${disabledReason ? ` ${reasonId}` : ""}`}
            aria-label={
              primary === "stop"
                ? "Stop auto spins"
                : primary === "skip"
                  ? "Skip animation"
                  : "Spin"
            }
            title={disabledReason}
            disabled={s.spinDisabled}
            onClick={a.spin}
          >
            <span className="sc-icon" aria-hidden="true">
              {icon[primary]}
            </span>
            <span className="sc-sr-only">{primary}</span>
          </button>
          <span id={chargeId} className="sc-sr-only" data-testid="charge-note">
            {"amount" in s.charge ? `Cost ${s.charge.amount}` : s.charge.label}
          </span>
          {disabledReason && (
            <span id={reasonId} className="sc-sr-only" role="status">
              {disabledReason}
            </span>
          )}
        </div>
        {circle("buy", d.buy)}
      </div>
    </aside>
  );
}

